// Frames can come from JavaScript data too, and join frames from the database.
const targets = pl.DataFrame({ category: ['Coffee', 'Tea', 'Gear', 'Snacks'], target: [4000, 4000, 12000, 1500] }, { schema: { category: pl.String, target: pl.Float64 } });
return _2.join(targets, { on: 'category' })
  .withColumns(col('revenue').truediv(col('target')).mul(100).round(1).alias('pct_of_target'));
